    "def verifier_largeur(largeur):\n",
    "    if largeur < 0:\n",
    "        raise ValueError(\"La largeur doit être positive ou nulle\")\n",
    "    return largeur\n",
    "\n",
    "print(\"Entrée valide :\", verifier_largeur(2))\n",
    "try:\n",
    "    verifier_largeur(-2)\n",
    "except ValueError:\n",
    "    print(\"Entrée invalide repérée\")\n"
   ],
