    "positions_exemple = [0.2, 0.8]\n",
    "plt.eventplot([positions_exemple], colors=[\"navy\"])\n",
    "plt.xlim(0, 1)\n",
    "plt.xlabel(\"Position relative dans le flux\")\n",
    "plt.yticks([0], [\"exemple : forêt\"])\n",
    "plt.show()\n"
