    "citations = json.loads((RESSOURCES / \"citations_gemini.json\").read_text(encoding=\"utf-8\"))\n",
    "print(\"Corpus et ressources vérifiés.\")\n",
    "texte_gemini = (RESSOURCES / \"gemini_transcription.txt\").read_bytes().decode(\"utf-8\")\n"
